/* Manager Overview uses the current blue portal world. */
.manager-portal-home {gap:24px;}
.manager-portal-home .dashboard-hero {min-height:0;padding:8px 0 20px;background:none;border:0;border-radius:0;box-shadow:none;overflow:visible;display:flex;gap:24px;align-items:center;justify-content:space-between;}
.manager-portal-home .dashboard-hero::after {display:none;}
.manager-portal-home .dashboard-hero-copy {width:auto;flex:1;min-width:0;max-width:720px;gap:8px;}
.manager-portal-home .dashboard-hero h1 {font:500 32px/1.2 var(--design-font-body);letter-spacing:-.03em;margin:0;text-wrap:balance;color:var(--design-text-primary);}
.manager-portal-home .dashboard-hero-copy>span {font:400 14px/1.6 var(--design-font-body);color:var(--design-text-secondary);}
.manager-portal-home .dashboard-hero-actions {margin:0;display:flex;gap:12px;align-self:center;flex-wrap:wrap;justify-content:flex-end;}
.manager-portal-home .dashboard-week-nav {grid-template-columns:44px minmax(134px,auto) 44px;min-height:48px;padding:0;border-radius:var(--design-radius-control);border:1px solid var(--design-border);background:white;box-shadow:none;backdrop-filter:none;}
.manager-portal-home .dashboard-week-nav>a {min-height:44px;min-width:44px;display:grid;place-items:center;color:var(--design-accent-ink);}
.manager-portal-home .dashboard-week-label {padding:0 4px;}
.manager-portal-home .dashboard-week-label strong {font:500 12px/1.5 var(--design-font-body);}
.manager-portal-home .dashboard-hero .button.primary {height:48px;min-height:48px;padding:0 18px;border-radius:var(--design-radius-control);box-shadow:none;font:600 13px/1.5 var(--design-font-body);gap:8px;}
.manager-portal-home .dashboard-tabs {margin:0;border-bottom:1px solid var(--design-border);gap:24px;overflow-x:auto;}
.manager-portal-home .dashboard-tabs a {font:500 13px/1.5 var(--design-font-body);min-height:48px;min-width:44px;padding:0 0 12px;color:var(--design-text-secondary);white-space:nowrap;}
.manager-portal-home .dashboard-tabs a.active {color:var(--design-accent-ink);}
.manager-portal-home .dashboard-tabs a.active::after {background:var(--design-primary);height:2px;}
.manager-portal-home .manager-home-grid {grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:24px;align-items:start;}
.manager-monitor-block {min-width:0;}
.manager-portal-home .manager-live-card {border:1px solid var(--design-border);border-radius:var(--design-radius-card);box-shadow:none;background:var(--design-surface-elevated);}
.manager-portal-home .manager-home-card-header {padding:24px;min-height:0;}
.manager-portal-home .manager-home-card-header h2 {font:500 22px/1.3 var(--design-font-body);letter-spacing:-.025em;color:var(--design-text-primary);}
.manager-portal-home .manager-home-count {font:500 18px/1.3 var(--design-font-body);width:36px;height:36px;font-variant-numeric:tabular-nums;background:var(--design-surface-inset);color:var(--design-text-primary);}
.manager-portal-home .manager-live-summary {padding:16px 24px;gap:24px;font-size:12px;color:var(--design-text-secondary);background:var(--design-surface-inset);}
.manager-portal-home .manager-live-summary strong {font-size:18px;font-weight:500;color:var(--design-text-primary);margin-right:4px;}
.manager-portal-home .manager-floor-row {padding:20px 24px;gap:12px;}
.manager-portal-home .manager-floor-person {gap:12px;}
.manager-portal-home .manager-floor-avatar {background:var(--design-surface-inset);color:var(--design-text-primary);font-family:var(--design-font-body);}
.manager-portal-home .manager-floor-copy strong {font:600 14px/1.4 var(--design-font-body);color:var(--design-text-primary);}
.manager-portal-home .manager-floor-copy small {color:var(--design-text-secondary);font-size:12px;line-height:1.55;}
.manager-portal-home .manager-floor-status {font:500 11px/1.5 var(--design-font-body);padding:5px 9px;}
.manager-portal-home .manager-live-footer {padding:16px 24px;align-items:center;}
.manager-portal-home .manager-live-refresh {border-radius:var(--design-radius-control);font:500 12px/1.4 var(--design-font-body);color:var(--design-text-primary);background:var(--design-surface-elevated);}
.manager-portal-home .manager-live-footer small {font-size:11px;line-height:1.6;color:var(--design-text-secondary);}
.manager-attendance-link {display:flex;align-items:center;gap:8px;min-height:44px;width:max-content;max-width:100%;margin:8px 0 0 4px;font-size:13px;font-weight:500;color:var(--design-accent-ink);}
.manager-attendance-link:hover {text-decoration:underline;text-underline-offset:3px;}
.manager-week-overview {border:1px solid var(--design-border);border-radius:var(--design-radius-card);background:var(--design-surface-elevated);padding:24px;color:var(--design-text-primary);min-width:0;}
.manager-week-overview>header {display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:24px;}
.manager-week-overview h2 {margin:0;font:500 22px/1.3 var(--design-font-body);letter-spacing:-.025em;}
.manager-week-overview header p {font-size:13px;line-height:1.6;color:var(--design-text-secondary);margin:8px 0 0;}
.manager-week-overview header a {display:flex;gap:8px;align-items:center;min-height:44px;min-width:44px;font-size:13px;font-weight:500;color:var(--design-accent-ink);white-space:nowrap;}
.manager-week-overview header a:hover {text-decoration:underline;text-underline-offset:3px;}
.manager-week-content {display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:32px;}
.manager-week-chart {min-width:0;}
.manager-chart-total {font-size:13px;color:var(--design-text-secondary);margin:0 0 20px;}
.manager-chart-total strong {font-size:26px;line-height:1.2;font-weight:500;color:var(--design-text-primary);font-variant-numeric:tabular-nums;margin-right:6px;}
.manager-week-chart ol {display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:14px;list-style:none;margin:0;padding:0;}
.manager-week-chart li {display:flex;flex-direction:column;align-items:center;gap:8px;min-width:0;}
.manager-bar-value {font-size:12px;font-weight:500;font-variant-numeric:tabular-nums;color:var(--design-text-primary);}
.manager-bar-track {height:100px;width:100%;max-width:42px;display:flex;align-items:end;border-bottom:1px solid var(--design-border);}
.manager-bar-track>span {display:block;width:100%;background:var(--design-primary);border-radius:6px 6px 0 0;transition:background 180ms ease;}
.manager-week-chart li:hover .manager-bar-track>span {background:var(--design-accent);}
.manager-week-chart time {display:grid;text-align:center;gap:4px;font-size:12px;line-height:1.4;color:var(--design-text-secondary);}
.manager-week-chart time small {font:400 11px/1.4 var(--design-font-mono);}
.manager-chart-note {margin:20px 0 0;color:var(--design-text-secondary);font-size:11px;line-height:1.6;}
.manager-location-plan {border-left:1px solid var(--design-border);padding-left:32px;min-width:0;}
.manager-location-plan h3 {font-size:14px;font-weight:600;margin:0 0 12px;}
.manager-location-plan ul {list-style:none;margin:0;padding:0;}
.manager-location-plan li {display:flex;gap:10px;align-items:center;padding:16px 0;border-bottom:1px solid var(--design-border);}
.manager-location-plan li:last-child {border:0;}
.manager-location-plan li>svg {flex:0 0 auto;color:var(--design-text-secondary);}
.manager-location-plan li>div {display:grid;gap:5px;flex:1;min-width:0;}
.manager-location-plan strong {font-size:13px;font-weight:500;overflow-wrap:anywhere;}
.manager-location-plan li>div>span {font-size:12px;line-height:1.5;color:var(--design-text-secondary);}
.manager-location-state {font-size:11px;color:var(--design-text-secondary);background:var(--design-surface-inset);padding:4px 8px;border-radius:var(--design-radius-pill);}
.manager-location-state[data-state='PUBLISHED'],.manager-location-state[data-state='READY'] {color:var(--color-state-success);background:var(--color-state-success-bg);}
.manager-portal-home a:focus-visible,.manager-portal-home button:focus-visible {outline:3px solid var(--design-accent-ink);outline-offset:3px;}
.manager-portal-home ::selection {background:#F8D4C8;color:var(--design-text-primary);}
