/* Current Home: weekly planning followed by attention, with live activity alongside. */
.manager-portal-home { gap: 28px; }
.manager-portal-home .dashboard-hero { padding: 0; gap: 24px; }
.manager-portal-home .dashboard-hero h1 { font-size: 30px; }
.manager-portal-home .dashboard-hero-actions { flex-direction: row; align-items: center; gap: 12px; }
.manager-portal-home .dashboard-week-nav { border-color: var(--design-border); border-radius: 14px; }
.manager-portal-home .dashboard-week-nav > a { color: var(--design-text-secondary); }
.manager-portal-home .dashboard-week-label svg { display: none; }
.manager-portal-home .dashboard-hero .button.primary { font-size: 13px; }
.manager-portal-home .dashboard-tabs { gap: 28px; border-color: var(--design-border); }
.manager-portal-home .dashboard-tabs a { padding-bottom: 12px; }
.manager-planning-summary { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); margin: 0; padding: 8px 0 4px; }
.manager-planning-summary > div { min-width: 0; padding: 4px 28px; border-left: 1px solid var(--design-border); }
.manager-planning-summary > div:first-child { padding-left: 0; border: 0; }
.manager-planning-summary dt { color: var(--design-text-secondary); font-size: 13px; line-height: 1.5; }
.manager-planning-summary dd { color: var(--design-text-primary); font-size: 32px; line-height: 1.3; font-weight: 500; letter-spacing: -.03em; font-variant-numeric: tabular-nums; margin: 8px 0 4px; }
.manager-planning-summary dd span { color: #758096; font-size: 20px; font-weight: 400; }
.manager-planning-summary small { display: block; margin-top: 4px; color: var(--design-text-secondary); font-size: 11px; font-weight: 400; letter-spacing: normal; line-height: 1.5; }
.manager-portal-home .manager-home-grid { grid-template-columns: minmax(0,1.5fr) minmax(0,1fr); gap: 24px; }
.manager-overview-rail { display: grid; align-content: start; gap: 24px; min-width: 0; }
.manager-portal-home .manager-home-card-header { padding: 20px 24px; }
.manager-portal-home .manager-home-card-header h2 { font-size: 18px; }
.manager-portal-home .manager-home-count { width: 30px; height: 30px; font-size: 16px; }
.manager-portal-home .manager-live-summary { padding: 12px 24px; font-size: 12px; gap: 20px; }
.manager-portal-home .manager-live-summary strong { font-size: 20px; }
.manager-portal-home .manager-home-empty { min-height: 112px; padding: 24px; align-items: start; text-align: left; justify-content: center; }
.manager-portal-home .manager-home-empty strong { font-size: 14px; font-weight: 500; }
.manager-portal-home .manager-home-empty small { font-size: 12px; line-height: 1.6; }
.manager-portal-home .manager-live-footer { padding: 12px 24px; }
.manager-portal-home .manager-live-footer small { max-width: 200px; }
.manager-portal-home .manager-live-refresh { padding: 8px 12px; min-width: 68px; }
.manager-portal-home .manager-attendance-link { font-size: 12px; margin-left: 4px; }
.manager-portal-home .manager-week-overview { padding: 24px; }
.manager-portal-home .manager-week-overview > header { flex-direction: column; gap: 4px; margin-bottom: 16px; }
.manager-portal-home .manager-week-overview h2 { font-size: 18px; }
.manager-portal-home .manager-week-overview header p { margin-top: 6px; font-size: 12px; }
.manager-portal-home .manager-week-content { grid-template-columns: minmax(0,1fr); gap: 20px; }
.manager-portal-home .manager-chart-total { margin-bottom: 16px; font-size: 12px; }
.manager-portal-home .manager-chart-total strong { font-size: 22px; }
.manager-portal-home .manager-week-chart ol { gap: 8px; }
.manager-portal-home .manager-bar-track { height: 72px; max-width: 28px; }
.manager-portal-home .manager-location-plan { padding: 20px 0 0; border-left: 0; border-top: 1px solid var(--design-border); }
.manager-portal-home .manager-location-plan h3 { font-weight: 500; }
.manager-portal-home .manager-location-plan li { padding: 12px 0; }
.manager-portal-home ::selection { background: #DCE9FF; color: var(--design-text-primary); }
.manager-portal-home .auth-disclosure-symbol { display: grid; place-items: center; flex: none; width: 26px; height: 26px; border: 1px solid var(--design-border); border-radius: 50%; color: var(--design-text-secondary); }
.manager-portal-home .auth-disclosure-symbol svg { grid-area: 1/1; }
.manager-portal-home .auth-disclosure-open { display: none; }
.manager-portal-home details[open] > summary .auth-disclosure-open { display: block; }
.manager-portal-home details[open] > summary .auth-disclosure-closed { display: none; }
@media (max-width:1200px) {
 .manager-portal-home .dashboard-hero { align-items: start; }
