 .manager-portal-home .dashboard-hero-actions { display: grid; grid-template-columns: minmax(0,1fr) auto; width: 100%; gap: 10px; }
 .manager-portal-home .dashboard-week-nav { grid-template-columns: 44px minmax(0,1fr) 44px; }
 .manager-portal-home .dashboard-week-label { min-width: 0; padding: 0; }
 .manager-portal-home .dashboard-week-label strong { font-size: 11px; }
 .manager-portal-home .dashboard-hero .button.primary { padding-inline: 14px; font-size: 12px; }
 html body .app-shell.nevora-portal .manager-portal-home .dashboard-tabs { display: flex; overflow-x: auto; gap: 24px; padding-inline: 0; }
 html body .app-shell.nevora-portal .manager-portal-home .dashboard-tabs a { flex: none; min-height: 44px; padding: 0 0 12px; }
 .manager-planning-summary { padding-top: 0; }
 .manager-planning-summary > div { padding: 4px 14px; }
 .manager-planning-summary dt { font-size: 11px; }
