html body{margin:0;font-family:var(--design-font-body,Inter,sans-serif)}.app-shell.nevora-portal{--design-text-primary:#111827;--design-text-secondary:#4B5563;--design-surface-elevated:#FFFFFF;--design-font-body:Inter,-apple-system,BlinkMacSystemFont,sans-serif;--design-radius-pill:999px;}
/* Jose's current portal direction: quiet white surfaces and the approved auth blue. */
html body .app-shell.nevora-portal {
  --design-primary: #0756D9;
  --design-accent: #003AAE;
  --design-accent-ink: #0756D9;
  --design-accent-ink-hover: #003AAE;
  --design-primary-light: #EDF4FF;
  --design-background: #F7F8FA;
  --design-secondary: #F7F8FA;
  --design-border: #E3E7EE;
  --design-surface: #E7EBF0;
  --design-surface-inset: #F4F6F9;
  --design-radius-card: 20px;
  --design-radius-control: 14px;
  --nevora-blue: var(--design-primary);
  --nevora-blue-hover: var(--design-accent);
  --nevora-cyan: #43CCFB;
  --nevora-soft: #EDF4FF;
  --nevora-accent-rgb: 7, 86, 217;
  --nevora-highlight-rgb: 67, 204, 251;
  --nevora-soft-rgb: 237, 244, 255;
  --nuvora-indigo: var(--design-primary);
  --nuvora-indigo-hover: var(--design-accent);
  --nuvora-indigo-soft: var(--nevora-soft);
  --color-brand-accent: var(--design-primary);
  --color-bg-main: var(--design-background);
  --color-bg-surface: #FFFFFF;
  --color-border-subtle: var(--design-border);
  --canvas: var(--design-background);
  --coffee: var(--design-primary);
  --coffee-dark: var(--design-accent);
  --caramel: var(--design-primary);
  --soft-caramel: var(--nevora-soft);
  --blue: var(--design-primary);
  --soft-blue: var(--nevora-soft);
  --employee-brand-soft: var(--nevora-soft);
  --fuel-ivory: var(--design-background);
  --fuel-coffee: var(--design-text-primary);
  --portal-nav-fill: var(--nevora-soft);
  --portal-focus: var(--design-primary);
  background: var(--design-background);
}

html body .app-shell.nevora-portal .sidebar {
  background: var(--design-surface-elevated);
  border-right: 1px solid var(--design-border);
  color: var(--design-text-primary);
  gap: 24px;
}
html body .app-shell.nevora-portal .sidebar-heading { gap: 8px; min-height: 52px; }
html body .app-shell.nevora-portal .login-brand-lockup {
  display: inline-flex; flex-direction: column; align-items: center; gap: 5px;
  width: 136px; color: var(--design-text-primary);
}
html body .app-shell.nevora-portal .login-brand-lockup .brand-wordmark { display: block; width: 100%; height: auto; }
html body .app-shell.nevora-portal .login-brand-module {
  font: 400 10px/1.5 var(--design-font-body); letter-spacing: .12em; color: var(--design-text-secondary);
}
html body .app-shell.nevora-portal .sidebar-toggle {
  border: 0; color: var(--design-text-secondary); background: transparent; border-radius: 12px;
}
html body .app-shell.nevora-portal .sidebar-toggle:hover { background: var(--design-surface-inset); color: var(--design-primary); }
html body .app-shell.nevora-portal .sidebar .nav-link { color: var(--design-text-secondary); font-weight: 450; }
html body .app-shell.nevora-portal .sidebar .nav-link:hover { background: var(--design-surface-inset); color: var(--design-text-primary); }
html body .app-shell.nevora-portal .sidebar .nav-link.active { background: var(--nevora-soft); color: var(--design-primary); font-weight: 550; }
html body .app-shell.nevora-portal .sidebar .nav-link.active .nav-icon { color: var(--design-primary); }
html body .app-shell.nevora-portal .sidebar-group-label { color: var(--design-text-secondary); font-size: 11px; font-weight: 450; }
html body .app-shell.nevora-portal .sidebar-nav { gap: 24px; scrollbar-color: #D2D9E3 transparent; }
html body .app-shell.nevora-portal .sidebar-profile { border-color: var(--design-border); color: var(--design-text-primary); }
html body .app-shell.nevora-portal .sidebar-profile .avatar { background: var(--nevora-soft); color: var(--design-primary); font-weight: 550; }
html body .app-shell.nevora-portal .sidebar-profile strong { color: var(--design-text-primary); font-size: 12px; font-weight: 500; }
html body .app-shell.nevora-portal .sidebar-profile-chevron { color: var(--design-text-secondary); }
html body .app-shell.nevora-portal .sidebar :is(.sidebar-logout-row,.sidebar-platform-footer,.sidebar-platform-footer small) { color: var(--design-text-secondary); }
html body .app-shell.nevora-portal .sidebar-logout-row:hover { background: var(--design-surface-inset); }
html body .app-shell.nevora-portal .sidebar[data-collapsed="true"] .login-brand-lockup { width: 54px; }
html body .app-shell.nevora-portal .sidebar[data-collapsed="true"] .login-brand-module { font-size: 8px; letter-spacing: .02em; }

html body .app-shell.nevora-portal .mobile-header { background: var(--design-background); border-color: var(--design-border); }
html body .app-shell.nevora-portal .portal-workspace-name { font-weight: 450; }
html body .app-shell.nevora-portal .mobile-header-actions { gap: 8px; }
html body .app-shell.nevora-portal .portal-notification-bell,
html body .app-shell.nevora-portal .mobile-header .nevora-action-menu-trigger {
  width: 44px; min-width: 44px; height: 44px; padding: 0; border: 1px solid var(--design-border);
  border-radius: 12px; color: var(--design-text-secondary); background: var(--design-surface-elevated); box-shadow: none;
}
html body .app-shell.nevora-portal .portal-notification-bell:hover,
html body .app-shell.nevora-portal .mobile-header .nevora-action-menu-trigger:hover {
  background: var(--nevora-soft); color: var(--design-primary); border-color: #D7E5FC;
}
html body .app-shell.nevora-portal .portal-notification-bell[aria-current="page"] { color: var(--design-primary); background: var(--nevora-soft); }
html body .app-shell.nevora-portal .portal-notification-count { background: var(--design-primary); border-color: var(--design-background); }
html body .app-shell.nevora-portal .mobile-nav { background: var(--design-surface-elevated); border-color: var(--design-border); box-shadow: none; }
html body .app-shell.nevora-portal .mobile-nav-link { color: var(--design-text-secondary); }
html body .app-shell.nevora-portal .mobile-nav-link.active { background: var(--nevora-soft); color: var(--design-primary); }
html body .app-shell.nevora-portal .mobile-nav-link.active svg { color: var(--design-primary); }
html body .app-shell.nevora-portal .nevora-action-menu-popover {
  border-color: var(--design-border); border-radius: 18px; background: white;
  box-shadow: 0 12px 40px #17254014; padding: 8px;
}
html body .app-shell.nevora-portal .nevora-action-menu-item { color: var(--design-text-primary); font-weight: 450; border-radius: 10px; }
html body .app-shell.nevora-portal .nevora-action-menu-item:is(:hover,[aria-current="page"]) { background: var(--nevora-soft); color: var(--design-primary); }

/* Blue brand fills need white labels. Functional warning/danger/success colors retain their meaning. */
html body .app-shell.nevora-portal :is(.button.primary,.ncc-button.primary,.pw-button:not(.pw-secondary):not(.pw-danger),
  .manager-home-action,.time-clock-button.clock-in,.schedule-builder-add,.new-shift-action.primary,
  .marketplace-claim,.marketplace-primary-action,.availability-preferences-button.primary,.manager-subtab-action,
  .employee-profile-view,.timeoff-settings-submit,.schedule-settings-save-btn,.employee-action.primary,
  .portal-device-button.primary,.schedule-generation-action.primary,.employee-time-correction-submit,.manager-correction-actions button.primary) {
  background: var(--design-primary); border-color: var(--design-primary); color: #FFFFFF;
}
html body .app-shell.nevora-portal :is(.button.primary,.ncc-button.primary,.pw-button:not(.pw-secondary):not(.pw-danger),
  .manager-home-action,.time-clock-button.clock-in,.schedule-builder-add,.new-shift-action.primary,
  .marketplace-claim,.marketplace-primary-action,.availability-preferences-button.primary,.manager-subtab-action,
  .employee-profile-view,.timeoff-settings-submit,.schedule-settings-save-btn,.employee-action.primary,
  .portal-device-button.primary,.schedule-generation-action.primary,.employee-time-correction-submit,.manager-correction-actions button.primary):is(:hover,:active):not(:disabled) {
  background: var(--design-accent); border-color: var(--design-accent); color: #FFFFFF;
}

@media (max-width:760px) {
  html body .app-shell.nevora-portal .mobile-header { padding: 12px 20px; min-height: 76px; }
  html body .app-shell.nevora-portal .mobile-header > .brand { min-height: 44px; }
  html body .app-shell.nevora-portal .mobile-header .login-brand-lockup { width: 136px; }
  html body .app-shell.nevora-portal .page-frame { padding: 24px 20px 112px; }
}
@media (max-width:360px) {
  html body .app-shell.nevora-portal .mobile-header { padding-inline: 16px; }
  html body .app-shell.nevora-portal .mobile-header .login-brand-lockup { width: 124px; }
  html body .app-shell.nevora-portal .page-frame { padding-inline: 16px; }
}
@media (prefers-reduced-motion:reduce) {
  html body .app-shell.nevora-portal :is(.nav-link,.sidebar-toggle,.portal-notification-bell,.nevora-action-menu-trigger) { transition: none; }
}

.root {border:1px solid var(--design-border);background:var(--design-surface-elevated);border-radius:var(--design-radius-card);padding:24px;min-width:0;display:grid;gap:20px;color:var(--design-text-primary);align-content:start;}
.root header {display:flex;gap:12px;align-items:center;flex-wrap:wrap;}
.root header>div {flex:1;min-width:0;}
.root h2 {font-size:22px;font-weight:500;letter-spacing:-.025em;margin:0;line-height:1.3;}
.root header p {font-size:13px;margin:6px 0 0;color:var(--design-text-secondary);}
.root header button {font:500 12px/1.3 var(--design-font-body);gap:7px;border-radius:var(--design-radius-control);box-shadow:none;min-height:44px;padding:0 12px;}
.total {display:grid;place-items:center;min-width:36px;min-height:36px;padding:4px 8px;background:var(--design-surface-inset);border-radius:var(--design-radius-pill);font-size:18px;font-weight:500;font-variant-numeric:tabular-nums;}
.counts {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;margin:0;background:var(--design-surface-inset);border-radius:12px;padding:4px;}
.counts button {display:grid;gap:8px;padding:12px 14px;text-align:left;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--design-text-primary);cursor:pointer;min-height:84px;min-width:0;font:inherit;transition:background 180ms ease,border-color 180ms ease;}
.counts button:hover {background:var(--design-surface-elevated);}
.counts button[aria-pressed=true] {background:var(--design-surface-elevated);border-color:var(--design-accent-ink);}
.counts button span {font-size:12px;color:var(--design-text-secondary);}
.counts button strong {font-size:26px;line-height:1.15;font-weight:500;font-variant-numeric:tabular-nums;}
.filterBar {display:flex;align-items:center;justify-content:space-between;gap:12px;margin-top:-12px;}
.filterBar button {min-height:44px;min-width:88px;padding:8px 12px;border:1px solid var(--design-border);border-radius:var(--design-radius-control);background:transparent;font:500 12px/1.4 var(--design-font-body);color:var(--design-text-primary);cursor:pointer;}
.filterBar button[aria-pressed=true] {background:var(--design-surface-inset);border-color:var(--design-text-secondary);}
.filterBar p {font-size:11px;line-height:1.5;color:var(--design-text-secondary);margin:0;text-align:right;}
.list {display:grid;}
.list article {display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:12px;align-items:start;padding:20px 0;border-bottom:1px solid var(--design-border);}
.list article:first-child {padding-top:0;}
.list article:last-child {padding-bottom:0;border-bottom:0;}
.icon {display:grid;place-items:center;min-height:36px;background:var(--design-surface-inset);border-radius:10px;color:var(--design-text-secondary);}
.copy {min-width:0;overflow-wrap:anywhere;}
.copy small {font-size:11px;color:var(--design-text-secondary);line-height:1.5;}
.copy small.priority {color:var(--design-accent-ink);font-weight:600;}
.copy h3 {font-size:15px;font-weight:600;line-height:1.4;margin:5px 0;letter-spacing:-.015em;}
.copy p {font-size:13px;color:var(--design-text-secondary);line-height:1.55;margin:0;}
.review {min-height:44px;min-width:88px;max-width:100%;padding:8px 10px;display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--design-border);border-radius:var(--design-radius-control);font-size:12px;font-weight:500;color:var(--design-text-primary);transition:background 180ms ease,border-color 180ms ease;align-self:center;}
.review svg {flex-shrink:0;}
.review:hover {background:var(--design-surface-inset);border-color:var(--design-text-secondary);}
.provenance {border-top:1px solid var(--design-border);padding-top:12px;display:flex;gap:8px 20px;flex-wrap:wrap;align-items:start;justify-content:space-between;}
.provenance>p {color:var(--design-text-secondary);font-size:11px;line-height:1.6;margin:12px 0;}
.note {color:var(--design-text-secondary);font-size:12px;line-height:1.6;max-width:65ch;}
.note summary {cursor:pointer;display:flex;align-items:center;min-height:44px;text-decoration:underline;text-underline-offset:3px;}
.note summary::before {content:'';display:inline-block;width:6px;height:6px;border-right:1px solid currentColor;border-bottom:1px solid currentColor;transform:rotate(-45deg);margin-right:10px;}
.note[open] summary::before {transform:rotate(45deg);}
.note p {margin:4px 0 12px;}
.status {font-size:14px;color:var(--design-text-secondary);line-height:1.6;padding:24px 0;min-height:120px;margin:0;max-width:65ch;}
.root footer {border-top:1px solid var(--design-border);padding-top:8px;display:grid;grid-template-columns:1fr 1.25fr;gap:8px;}
.root footer a {display:flex;gap:8px;align-items:center;color:var(--design-accent-ink);font-size:12px;font-weight:500;min-height:44px;}
.root footer a svg {flex-shrink:0;}
.root footer a:hover {text-decoration:underline;text-underline-offset:3px;}
.root button:focus-visible,.root a:focus-visible,.root summary:focus-visible {outline:3px solid var(--design-accent-ink);outline-offset:3px;}
@media(max-width:1100px){.root footer {grid-template-columns:1fr;}}
@media(max-width:600px){.root {padding:20px;gap:20px;}.root h2 {font-size:20px;}.root header {position:relative;padding-bottom:50px;}.root header button {position:absolute;bottom:0;left:0;}.counts button {padding:12px 6px;min-height:80px;}.counts button span {font-size:11px;}.counts button strong {font-size:24px;}.list article {grid-template-columns:28px minmax(0,1fr);gap:10px;}.icon {min-height:28px;border-radius:8px;}.icon svg {width:18px;height:18px;}.review {grid-column:2;width:max-content;margin-top:2px;}.copy h3 {font-size:15px;}.provenance {gap:0;}.root footer a {font-size:13px;}.root footer {grid-template-columns:1fr;}}
@media(prefers-reduced-motion:reduce){.review,.counts button {transition:none;}}

.actionGroup { border-bottom:1px solid var(--design-border); padding:12px 0; }
.actionGroup summary { display:flex; justify-content:space-between; align-items:center; gap:16px; min-height:64px; cursor:pointer; list-style:none; }
.actionGroup summary::-webkit-details-marker { display:none; }
.actionGroup summary>span:first-child { display:grid; gap:6px; }
.actionGroup summary small { color:var(--design-accent-ink); font-size:11px; font-weight:550; }
.actionGroup summary strong { font-size:15px; font-weight:550; }
.groupCount { display:flex; align-items:center; gap:8px; color:var(--design-text-secondary); font-size:13px; }
.actionGroup>div { margin:16px 0; padding-left:12px; border-left:2px solid var(--design-surface); }

.groupPreview{margin:12px 0;color:var(--design-text-secondary);font-size:12px;line-height:1.6;}

/* Compact queue controls; the protected projection and filter behavior are unchanged. */
.root {gap:16px;}
.root header {flex-wrap:nowrap;gap:10px;}
.root h2 {font-size:20px;}
.root header button {border:0;background:var(--design-surface-inset);padding:0 12px;color:var(--design-text-secondary);}
.total {min-width:28px;min-height:28px;font-size:14px;padding:4px 6px;}
.counts {display:flex;flex-wrap:wrap;gap:6px;background:none;padding:0;border-radius:0;}
.counts button {display:flex;align-items:center;justify-content:center;gap:6px;min-height:44px;padding:8px 10px;border:0;border-radius:10px;font-size:12px;font-weight:450;background:var(--design-surface-inset);}
.counts button span {font-size:12px;}
.counts button strong {font-size:12px;line-height:1.5;font-weight:550;}
.counts button[aria-pressed=true] {background:var(--nevora-soft,#EDF4FF);color:var(--design-accent-ink);border:0;}
.counts button[aria-pressed=true] span {color:inherit;}
.filterBar {margin-top:-4px;justify-content:flex-start;}
.filterBar p {text-align:left;}
.list article {padding:16px 0;grid-template-columns:32px minmax(0,1fr) auto;gap:10px;}
.icon {min-height:32px;}
.copy h3 {font-size:14px;font-weight:500;}
.copy p {font-size:12px;}
.review {min-width:72px;font-size:12px;border:0;background:var(--design-surface-inset);padding:8px 10px;border-radius:10px;}
.actionGroup {padding:8px 0;}
.actionGroup summary {min-height:56px;}
.actionGroup summary strong {font-size:14px;font-weight:500;}
.actionGroup summary small {font-size:10px;}
.actionGroup>div {padding-left:8px;}
.provenance {padding-top:8px;gap:4px 16px;}
.provenance>p {margin:8px 0;}
.note summary {text-decoration:none;}
.recovery {border-top:1px solid var(--design-border);padding-top:4px;}
.recovery>summary {display:flex;justify-content:space-between;gap:12px;min-height:44px;font-size:12px;color:var(--design-text-secondary);list-style:none;cursor:pointer;}
.recovery>summary::-webkit-details-marker {display:none;}
.recovery footer {border:0;padding-top:8px;grid-template-columns:1fr;gap:4px;}
@media(max-width:600px) {
 .root {padding:20px;gap:16px;}
 .root header {padding-bottom:0;}
 .root header button {position:static;padding:0;min-width:44px;width:44px;}
 .root header button span {position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;}
 .counts {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;}
 .counts button {min-height:44px;padding:8px 10px;}
 .list article {grid-template-columns:28px minmax(0,1fr);gap:10px;}
 .review {grid-column:2;width:max-content;}
 .provenance {gap:0;}
}

html body{margin:0;font-family:var(--design-font-body,Inter,sans-serif)}.app-shell.nevora-portal{--design-text-primary:#111827;--design-text-secondary:#4B5563;--design-surface-elevated:#FFFFFF;--design-font-body:Inter,-apple-system,BlinkMacSystemFont,sans-serif;--design-radius-pill:999px;}
/* Jose's current portal direction: quiet white surfaces and the approved auth blue. */
html body .app-shell.nevora-portal {
  --design-primary: #0756D9;
  --design-accent: #003AAE;
  --design-accent-ink: #0756D9;
  --design-accent-ink-hover: #003AAE;
  --design-primary-light: #EDF4FF;
  --design-background: #F7F8FA;
  --design-secondary: #F7F8FA;
  --design-border: #E3E7EE;
  --design-surface: #E7EBF0;
  --design-surface-inset: #F4F6F9;
  --design-radius-card: 20px;
  --design-radius-control: 14px;
  --nevora-blue: var(--design-primary);
  --nevora-blue-hover: var(--design-accent);
  --nevora-cyan: #43CCFB;
  --nevora-soft: #EDF4FF;
  --nevora-accent-rgb: 7, 86, 217;
  --nevora-highlight-rgb: 67, 204, 251;
  --nevora-soft-rgb: 237, 244, 255;
  --nuvora-indigo: var(--design-primary);
  --nuvora-indigo-hover: var(--design-accent);
  --nuvora-indigo-soft: var(--nevora-soft);
  --color-brand-accent: var(--design-primary);
  --color-bg-main: var(--design-background);
  --color-bg-surface: #FFFFFF;
  --color-border-subtle: var(--design-border);
  --canvas: var(--design-background);
  --coffee: var(--design-primary);
  --coffee-dark: var(--design-accent);
  --caramel: var(--design-primary);
  --soft-caramel: var(--nevora-soft);
  --blue: var(--design-primary);
  --soft-blue: var(--nevora-soft);
  --employee-brand-soft: var(--nevora-soft);
  --fuel-ivory: var(--design-background);
  --fuel-coffee: var(--design-text-primary);
  --portal-nav-fill: var(--nevora-soft);
  --portal-focus: var(--design-primary);
  background: var(--design-background);
}

html body .app-shell.nevora-portal .sidebar {
  background: var(--design-surface-elevated);
  border-right: 1px solid var(--design-border);
  color: var(--design-text-primary);
  gap: 24px;
}
html body .app-shell.nevora-portal .sidebar-heading { gap: 8px; min-height: 52px; }
html body .app-shell.nevora-portal .login-brand-lockup {
  display: inline-flex; flex-direction: column; align-items: center; gap: 5px;
  width: 136px; color: var(--design-text-primary);
}
html body .app-shell.nevora-portal .login-brand-lockup .brand-wordmark { display: block; width: 100%; height: auto; }
html body .app-shell.nevora-portal .login-brand-module {
  font: 400 10px/1.5 var(--design-font-body); letter-spacing: .12em; color: var(--design-text-secondary);
}
html body .app-shell.nevora-portal .sidebar-toggle {
  border: 0; color: var(--design-text-secondary); background: transparent; border-radius: 12px;
}
html body .app-shell.nevora-portal .sidebar-toggle:hover { background: var(--design-surface-inset); color: var(--design-primary); }
html body .app-shell.nevora-portal .sidebar .nav-link { color: var(--design-text-secondary); font-weight: 450; }
html body .app-shell.nevora-portal .sidebar .nav-link:hover { background: var(--design-surface-inset); color: var(--design-text-primary); }
html body .app-shell.nevora-portal .sidebar .nav-link.active { background: var(--nevora-soft); color: var(--design-primary); font-weight: 550; }
html body .app-shell.nevora-portal .sidebar .nav-link.active .nav-icon { color: var(--design-primary); }
html body .app-shell.nevora-portal .sidebar-group-label { color: var(--design-text-secondary); font-size: 11px; font-weight: 450; }
html body .app-shell.nevora-portal .sidebar-nav { gap: 24px; scrollbar-color: #D2D9E3 transparent; }
html body .app-shell.nevora-portal .sidebar-profile { border-color: var(--design-border); color: var(--design-text-primary); }
html body .app-shell.nevora-portal .sidebar-profile .avatar { background: var(--nevora-soft); color: var(--design-primary); font-weight: 550; }
html body .app-shell.nevora-portal .sidebar-profile strong { color: var(--design-text-primary); font-size: 12px; font-weight: 500; }
html body .app-shell.nevora-portal .sidebar-profile-chevron { color: var(--design-text-secondary); }
html body .app-shell.nevora-portal .sidebar :is(.sidebar-logout-row,.sidebar-platform-footer,.sidebar-platform-footer small) { color: var(--design-text-secondary); }
html body .app-shell.nevora-portal .sidebar-logout-row:hover { background: var(--design-surface-inset); }
html body .app-shell.nevora-portal .sidebar[data-collapsed="true"] .login-brand-lockup { width: 54px; }
html body .app-shell.nevora-portal .sidebar[data-collapsed="true"] .login-brand-module { font-size: 8px; letter-spacing: .02em; }

html body .app-shell.nevora-portal .mobile-header { background: var(--design-background); border-color: var(--design-border); }
html body .app-shell.nevora-portal .portal-workspace-name { font-weight: 450; }
html body .app-shell.nevora-portal .mobile-header-actions { gap: 8px; }
html body .app-shell.nevora-portal .portal-notification-bell,
html body .app-shell.nevora-portal .mobile-header .nevora-action-menu-trigger {
  width: 44px; min-width: 44px; height: 44px; padding: 0; border: 1px solid var(--design-border);
  border-radius: 12px; color: var(--design-text-secondary); background: var(--design-surface-elevated); box-shadow: none;
}
html body .app-shell.nevora-portal .portal-notification-bell:hover,
html body .app-shell.nevora-portal .mobile-header .nevora-action-menu-trigger:hover {
  background: var(--nevora-soft); color: var(--design-primary); border-color: #D7E5FC;
}
html body .app-shell.nevora-portal .portal-notification-bell[aria-current="page"] { color: var(--design-primary); background: var(--nevora-soft); }
html body .app-shell.nevora-portal .portal-notification-count { background: var(--design-primary); border-color: var(--design-background); }
html body .app-shell.nevora-portal .mobile-nav { background: var(--design-surface-elevated); border-color: var(--design-border); box-shadow: none; }
html body .app-shell.nevora-portal .mobile-nav-link { color: var(--design-text-secondary); }
html body .app-shell.nevora-portal .mobile-nav-link.active { background: var(--nevora-soft); color: var(--design-primary); }
html body .app-shell.nevora-portal .mobile-nav-link.active svg { color: var(--design-primary); }
html body .app-shell.nevora-portal .nevora-action-menu-popover {
  border-color: var(--design-border); border-radius: 18px; background: white;
  box-shadow: 0 12px 40px #17254014; padding: 8px;
}
html body .app-shell.nevora-portal .nevora-action-menu-item { color: var(--design-text-primary); font-weight: 450; border-radius: 10px; }
html body .app-shell.nevora-portal .nevora-action-menu-item:is(:hover,[aria-current="page"]) { background: var(--nevora-soft); color: var(--design-primary); }

/* Blue brand fills need white labels. Functional warning/danger/success colors retain their meaning. */
html body .app-shell.nevora-portal :is(.button.primary,.ncc-button.primary,.pw-button:not(.pw-secondary):not(.pw-danger),
  .manager-home-action,.time-clock-button.clock-in,.schedule-builder-add,.new-shift-action.primary,
  .marketplace-claim,.marketplace-primary-action,.availability-preferences-button.primary,.manager-subtab-action,
  .employee-profile-view,.timeoff-settings-submit,.schedule-settings-save-btn,.employee-action.primary,
  .portal-device-button.primary,.schedule-generation-action.primary,.employee-time-correction-submit,.manager-correction-actions button.primary) {
  background: var(--design-primary); border-color: var(--design-primary); color: #FFFFFF;
}
html body .app-shell.nevora-portal :is(.button.primary,.ncc-button.primary,.pw-button:not(.pw-secondary):not(.pw-danger),
  .manager-home-action,.time-clock-button.clock-in,.schedule-builder-add,.new-shift-action.primary,
  .marketplace-claim,.marketplace-primary-action,.availability-preferences-button.primary,.manager-subtab-action,
  .employee-profile-view,.timeoff-settings-submit,.schedule-settings-save-btn,.employee-action.primary,
  .portal-device-button.primary,.schedule-generation-action.primary,.employee-time-correction-submit,.manager-correction-actions button.primary):is(:hover,:active):not(:disabled) {
  background: var(--design-accent); border-color: var(--design-accent); color: #FFFFFF;
}

@media (max-width:760px) {
  html body .app-shell.nevora-portal .mobile-header { padding: 12px 20px; min-height: 76px; }
  html body .app-shell.nevora-portal .mobile-header > .brand { min-height: 44px; }
  html body .app-shell.nevora-portal .mobile-header .login-brand-lockup { width: 136px; }
  html body .app-shell.nevora-portal .page-frame { padding: 24px 20px 112px; }
}
@media (max-width:360px) {
  html body .app-shell.nevora-portal .mobile-header { padding-inline: 16px; }
  html body .app-shell.nevora-portal .mobile-header .login-brand-lockup { width: 124px; }
  html body .app-shell.nevora-portal .page-frame { padding-inline: 16px; }
}
@media (prefers-reduced-motion:reduce) {
  html body .app-shell.nevora-portal :is(.nav-link,.sidebar-toggle,.portal-notification-bell,.nevora-action-menu-trigger) { transition: none; }
}
/* Manager Overview uses the current blue portal world. */
.manager-portal-home {gap:24px;}
.manager-portal-home .dashboard-hero {min-height:0;padding:8px 0 20px;background:none;border:0;border-radius:0;box-shadow:none;overflow:visible;display:flex;gap:24px;align-items:center;justify-content:space-between;}
.manager-portal-home .dashboard-hero::after {display:none;}
.manager-portal-home .dashboard-hero-copy {width:auto;flex:1;min-width:0;max-width:720px;gap:8px;}
.manager-portal-home .dashboard-hero h1 {font:500 32px/1.2 var(--design-font-body);letter-spacing:-.03em;margin:0;text-wrap:balance;color:var(--design-text-primary);}
.manager-portal-home .dashboard-hero-copy>span {font:400 14px/1.6 var(--design-font-body);color:var(--design-text-secondary);}
.manager-portal-home .dashboard-hero-actions {margin:0;display:flex;gap:12px;align-self:center;flex-wrap:wrap;justify-content:flex-end;}
.manager-portal-home .dashboard-week-nav {grid-template-columns:44px minmax(134px,auto) 44px;min-height:48px;padding:0;border-radius:var(--design-radius-control);border:1px solid var(--design-border);background:white;box-shadow:none;backdrop-filter:none;}
.manager-portal-home .dashboard-week-nav>a {min-height:44px;min-width:44px;display:grid;place-items:center;color:var(--design-accent-ink);}
.manager-portal-home .dashboard-week-label {padding:0 4px;}
.manager-portal-home .dashboard-week-label strong {font:500 12px/1.5 var(--design-font-body);}
.manager-portal-home .dashboard-hero .button.primary {height:48px;min-height:48px;padding:0 18px;border-radius:var(--design-radius-control);box-shadow:none;font:600 13px/1.5 var(--design-font-body);gap:8px;}
.manager-portal-home .dashboard-tabs {margin:0;border-bottom:1px solid var(--design-border);gap:24px;overflow-x:auto;}
.manager-portal-home .dashboard-tabs a {font:500 13px/1.5 var(--design-font-body);min-height:48px;min-width:44px;padding:0 0 12px;color:var(--design-text-secondary);white-space:nowrap;}
.manager-portal-home .dashboard-tabs a.active {color:var(--design-accent-ink);}
.manager-portal-home .dashboard-tabs a.active::after {background:var(--design-primary);height:2px;}
.manager-portal-home .manager-home-grid {grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:24px;align-items:start;}
.manager-monitor-block {min-width:0;}
.manager-portal-home .manager-live-card {border:1px solid var(--design-border);border-radius:var(--design-radius-card);box-shadow:none;background:var(--design-surface-elevated);}
.manager-portal-home .manager-home-card-header {padding:24px;min-height:0;}
.manager-portal-home .manager-home-card-header h2 {font:500 22px/1.3 var(--design-font-body);letter-spacing:-.025em;color:var(--design-text-primary);}
.manager-portal-home .manager-home-count {font:500 18px/1.3 var(--design-font-body);width:36px;height:36px;font-variant-numeric:tabular-nums;background:var(--design-surface-inset);color:var(--design-text-primary);}
.manager-portal-home .manager-live-summary {padding:16px 24px;gap:24px;font-size:12px;color:var(--design-text-secondary);background:var(--design-surface-inset);}
.manager-portal-home .manager-live-summary strong {font-size:18px;font-weight:500;color:var(--design-text-primary);margin-right:4px;}
.manager-portal-home .manager-floor-row {padding:20px 24px;gap:12px;}
.manager-portal-home .manager-floor-person {gap:12px;}
.manager-portal-home .manager-floor-avatar {background:var(--design-surface-inset);color:var(--design-text-primary);font-family:var(--design-font-body);}
.manager-portal-home .manager-floor-copy strong {font:600 14px/1.4 var(--design-font-body);color:var(--design-text-primary);}
.manager-portal-home .manager-floor-copy small {color:var(--design-text-secondary);font-size:12px;line-height:1.55;}
.manager-portal-home .manager-floor-status {font:500 11px/1.5 var(--design-font-body);padding:5px 9px;}
.manager-portal-home .manager-live-footer {padding:16px 24px;align-items:center;}
.manager-portal-home .manager-live-refresh {border-radius:var(--design-radius-control);font:500 12px/1.4 var(--design-font-body);color:var(--design-text-primary);background:var(--design-surface-elevated);}
