.manager-attendance-link {display:flex;align-items:center;gap:8px;min-height:44px;width:max-content;max-width:100%;margin:8px 0 0 4px;font-size:13px;font-weight:500;color:var(--design-accent-ink);}
.manager-attendance-link:hover {text-decoration:underline;text-underline-offset:3px;}
.manager-week-overview {border:1px solid var(--design-border);border-radius:var(--design-radius-card);background:var(--design-surface-elevated);padding:24px;color:var(--design-text-primary);min-width:0;}
.manager-week-overview>header {display:flex;justify-content:space-between;gap:20px;align-items:start;margin-bottom:24px;}
.manager-week-overview h2 {margin:0;font:500 22px/1.3 var(--design-font-body);letter-spacing:-.025em;}
.manager-week-overview header p {font-size:13px;line-height:1.6;color:var(--design-text-secondary);margin:8px 0 0;}
.manager-week-overview header a {display:flex;gap:8px;align-items:center;min-height:44px;min-width:44px;font-size:13px;font-weight:500;color:var(--design-accent-ink);white-space:nowrap;}
.manager-week-overview header a:hover {text-decoration:underline;text-underline-offset:3px;}
.manager-week-content {display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:32px;}
.manager-week-chart {min-width:0;}
.manager-chart-total {font-size:13px;color:var(--design-text-secondary);margin:0 0 20px;}
.manager-chart-total strong {font-size:26px;line-height:1.2;font-weight:500;color:var(--design-text-primary);font-variant-numeric:tabular-nums;margin-right:6px;}
.manager-week-chart ol {display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:14px;list-style:none;margin:0;padding:0;}
.manager-week-chart li {display:flex;flex-direction:column;align-items:center;gap:8px;min-width:0;}
.manager-bar-value {font-size:12px;font-weight:500;font-variant-numeric:tabular-nums;color:var(--design-text-primary);}
