.manager-planning-summary small { display: block; margin-top: 4px; color: var(--design-text-secondary); font-size: 11px; font-weight: 400; letter-spacing: normal; line-height: 1.5; }
.manager-portal-home .manager-home-grid { grid-template-columns: minmax(0,1.5fr) minmax(0,1fr); gap: 24px; }
